/* W6.5: fictional arrival planning, not a visa/education/booking decision. RAM only. */
const ARRIVAL_ROUTES=['/portal/arrival','/staff/arrival'];
const ARRIVAL_TASKS={residence:['Wohnsitzanmeldung vorbereiten','Prepare residence registration'],permit:['Aufenthaltsrechtliche Schritte klären','Clarify residence-related next steps'],presence:['Präsenzumstellung zur Fachprüfung','Refer classroom transition for subject review']};
const ARRIVAL={role:'admin',draft:{date:'',time:'',flight:'',airport:'',reason:''},plans:[],actualDate:'',confirmed:false,arrival:null,revision:0,tasks:[],history:[],review:{date:'',note:'',checked:false},error:null};
function arrivalStaff(){return route()==='/staff/arrival'}
function arrivalAllowed(){return arrivalStaff()&&['admin','head'].includes(ARRIVAL.role)}
function arrivalClone(v){return JSON.parse(JSON.stringify(v))}
function arrivalDateValid(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const d=new Date(s+'T12:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===s}
function arrivalEvent(de,en,note=''){ARRIVAL.history.push({de,en,note,at:new Date().toISOString()})}
function arrivalButton(de,en,act){return `<button type="button" class="btn secondary" data-arrival-action="${act}">${t(de,en)}</button>`}
function arrivalFail(de,en){ARRIVAL.error=[de,en];render();document.getElementById('arrival-error')?.focus()}
function arrivalStatus(){return ARRIVAL.arrival?t('Ankunft selbst gemeldet · keine Behörden- oder Kursentscheidung','Arrival self-reported · no authority or course decision'):ARRIVAL.plans.length?t('Reise geplant · tatsächliche Ankunft unbestätigt','Travel planned · actual arrival unconfirmed'):t('Noch keine Reiseplanung hinterlegt','No travel plan recorded yet')}
function arrivalPlanSummary(p){return `<p>${t('Planfassung','Plan version')} ${p.version} · ${esc(p.date)} ${esc(p.time)} · ${esc(p.airport)} · ${esc(p.flight)}</p>${p.reason?`<p class="learning-preserve">${t('Änderungsgrund','Reason for change')}: ${esc(p.reason)}</p>`:''}`}
function arrivalTaskStatus(x){return x.status==='recorded'?t('Prüfstand dokumentiert · keine externe Erledigung','Review recorded · no external completion'):x.status==='clarify'?t('Rückfrage offen','Question pending'):t('Fachprüfung offen','Subject review pending')}
function arrivalTasksView(){return `<section class="learning-panel"><h2>${t('Anschlussprüfungen','Follow-up reviews')}</h2><p>${t('Aufgaben entstehen erst aus einer ausdrücklichen Ankunftsmeldung. Wohnsitzanmeldung, Aufenthaltstitel und Kurszuordnung werden hier nicht ausgeführt. Keine festen Behördenfristen oder Terminbuchungen.','Tasks arise only from an explicit arrival report. Residence registration, permits and course assignments are not performed here. No fixed authority deadlines or appointments.')}</p>${ARRIVAL.tasks.length?ARRIVAL.tasks.map(x=>`<article class="arrival-task"><h3>${t(...ARRIVAL_TASKS[x.kind])}</h3><p>${arrivalTaskStatus(x)} · ${t('Zuständigkeit im Muster','Sample responsibility')}: ${x.owner==='head'?t('Schulleitung','School lead'):t('Verwaltung','Administration')}</p><p>${t('Bezugsfassung der Ankunft','Arrival revision')}: ${x.revision}</p>${x.publicNote?`<p class="learning-preserve">${esc(x.publicNote)}</p>`:x.revision>1?`<p>${t('Ankunftsangabe geändert; erneute Prüfung erforderlich.','Arrival information changed; review required again.')}</p>`:''}${arrivalAllowed()&&x.owner===ARRIVAL.role?`<label class="field">${t('Interne Prüfnotiz · nur fiktiv','Internal review note · fictional only')}<textarea data-arrival-task-field="internal" data-task="${x.kind}" maxlength="1500">${esc(x.internal)}</textarea></label><label class="field">${t('Rückfrage / Bearbeitungsstand für Musterperson','Question / progress for sample person')}<textarea data-arrival-task-field="response" data-task="${x.kind}" maxlength="1500">${esc(x.response)}</textarea></label><label class="attendance-check"><input type="checkbox" data-arrival-task-field="checked" data-task="${x.kind}" ${x.checked?'checked':''}>${t('Aktuelle Ankunftsfassung und fachlichen Prüfbedarf geprüft','Current arrival revision and subject review needs checked')}</label><div class="actions"><button class="btn secondary" data-arrival-task-action="question" data-task="${x.kind}">${t('Rückfrage lokal bereitstellen','Record question locally')}</button><button class="btn secondary" data-arrival-task-action="record" data-task="${x.kind}">${t('Prüfstand lokal dokumentieren','Record review locally')}</button></div><details><summary>${t('Interne Prüfungshistorie','Internal review history')}</summary>${x.history.map(h=>`<article class="case-message"><p>${esc(h.at)} · ${t('Ankunftsfassung','Arrival revision')} ${h.revision}</p><p class="learning-preserve">${esc(h.internal)}</p><p>${esc(h.response)}</p></article>`).join('')}</details>`:!arrivalStaff()&&x.status==='clarify'?`<label class="field">${t('Eigene Ergänzung · fiktiv','Your additional information · fictional')}<textarea data-arrival-task-field="reply" data-task="${x.kind}" maxlength="1500">${esc(x.reply)}</textarea></label><button class="btn secondary" data-arrival-task-action="reply" data-task="${x.kind}">${t('Ergänzung lokal vormerken','Record additional information locally')}</button>`:''}${x.replies.map(r=>`<article class="case-message"><p>${t('Eigene Ergänzung','Your additional information')} · ${esc(r.at)} · ${t('Ankunftsfassung','Arrival revision')} ${r.revision}</p><p class="learning-preserve">${esc(r.text)}</p></article>`).join('')}</article>`).join(''):`<p class="learning-empty">${t('Keine Anschlussprüfungen: eine geplante Ankunft reicht nicht aus.','No follow-up reviews: a planned arrival is not sufficient.')}</p>`}</section>`}
function arrivalPage(){const staff=arrivalStaff(),allowed=!staff||arrivalAllowed(),p=ARRIVAL.plans.at(-1),d=ARRIVAL.draft;return `<section class="v2-content learning-journey arrival-journey"><span class="eyebrow">${t('ANKOMMEN · LOKALES MUSTER','ARRIVAL · LOCAL SAMPLE')}</span><h1 id="arrival-heading" tabindex="-1">${staff?t('Ankunft und nächste Schritte prüfen.','Review arrival and next steps.'):t('Deine Reise. Dein Ankommen.','Your journey. Your arrival.')}</h1><p class="learning-notice">${t('Nur fiktive Angaben im Arbeitsspeicher. Keine echte Reisebuchung, Nachricht, Rechtsauskunft, Visum- oder Kursentscheidung. Neuladen verwirft das Muster. Rollenwahl ist keine Anmeldung.','Fictional information in memory only. No actual travel booking, message, legal advice, visa or course decision. Reloading discards the sample. Role selection is not sign-in.')}</p><nav class="portal-nav"><a href="#/portal/arrival">${t('Eigene Ankunft · Demo','My arrival · demo')}</a><a href="#/staff/arrival">${t('Verwaltung · Musterrollen','Administration · sample roles')}</a><a href="#/portal/visa">${t('Visumübersicht · bestehender Pilot','Visa overview · existing pilot')}</a></nav>${staff?`<label class="field arrival-role">${t('Musterrolle','Sample role')}<select id="arrival-role"><option value="admin" ${ARRIVAL.role==='admin'?'selected':''}>${t('Verwaltung','Administration')}</option><option value="head" ${ARRIVAL.role==='head'?'selected':''}>${t('Schulleitung','School lead')}</option><option value="other" ${ARRIVAL.role==='other'?'selected':''}>${t('Nicht zugeordnete Rolle','Unassigned role')}</option></select></label>`:''}${ARRIVAL.error?`<p role="alert" tabindex="-1" id="arrival-error">${t(...ARRIVAL.error)}</p>`:''}${!allowed?`<p class="learning-empty">${t('Dieser Musterrolle ist kein Ankunftsvorgang zugeordnet.','No arrival record is assigned to this sample role.')}</p>`:`<section class="learning-panel"><h2>${t('DEMO-ARRIVAL-01 · aktueller Stand','DEMO-ARRIVAL-01 · current record')}</h2><p class="learning-status">${arrivalStatus()}</p>${p?arrivalPlanSummary(p):''}${ARRIVAL.arrival?`<p>${t('Gemeldetes tatsächliches Ankunftsdatum','Reported actual arrival date')}: ${esc(ARRIVAL.arrival.date)} · ${t('Fassung','Revision')} ${ARRIVAL.revision}</p>`:''}<p>${t('Ein verstrichener Planzeitpunkt bestätigt keine Ankunft. Planungsinformation erscheint hier lokal für Verwaltung und Schulleitung; nichts wird versendet.','A past planned time does not confirm arrival. Planning information appears here locally for administration and school lead; nothing is sent.')}</p></section>${!staff?`<section class="learning-panel"><h2>${t('Flugreise im Muster planen oder ändern','Plan or change a sample flight journey')}</h2><div class="case-fields"><label class="field">${t('Geplantes Datum','Planned date')}<input id="arrival-date" type="date" value="${esc(d.date)}"></label><label class="field">${t('Geplante Ortszeit','Planned local time')}<input id="arrival-time" type="time" value="${esc(d.time)}"></label><label class="field">${t('Flugnummer · fiktiv','Flight number · fictional')}<input id="arrival-flight" maxlength="60" value="${esc(d.flight)}"></label><label class="field">${t('Flughafen · fiktiv','Airport · fictional')}<input id="arrival-airport" maxlength="120" value="${esc(d.airport)}"></label></div><label class="field">${t('Änderungsgrund · ab zweiter Fassung erforderlich','Reason for change · required from second version')}<textarea id="arrival-reason" maxlength="1500">${esc(d.reason)}</textarea></label>${arrivalButton('Reiseplan lokal vormerken','Record travel plan locally','plan')}<p>${t('Dieses Teilmuster umfasst eine Flugreise; andere Reisearten und Benachrichtigungswege sind fachlich noch auszugestalten.','This partial sample covers a flight journey; other travel modes and notification channels remain to be designed.')}</p></section><section class="learning-panel"><h2>${t('Tatsächliche Ankunft melden','Report actual arrival')}</h2><label class="field">${t('Tatsächliches Datum · fiktiv','Actual date · fictional')}<input id="arrival-actual" type="date" value="${esc(ARRIVAL.actualDate)}"></label><label class="attendance-check"><input id="arrival-confirmed" type="checkbox" ${ARRIVAL.confirmed?'checked':''}>${t('Die Musterperson ist tatsächlich angekommen; keine bloße Planung','The sample person has actually arrived; this is not just planning')}</label>${arrivalButton('Ankunft lokal bestätigen','Confirm arrival locally','arrived')}<p>${t('Eine spätere Korrektur benötigt eine dokumentierte Verwaltungsprüfung. Kein Automatismus ändert Präsenz- oder Semesterzuordnung.','A subsequent correction requires a documented administration review. No automation changes classroom or semester assignment.')}</p></section>`:ARRIVAL.role==='admin'&&ARRIVAL.arrival?`<section class="learning-panel"><h2>${t('Ankunftsdatum nachvollziehbar korrigieren','Correct arrival date transparently')}</h2><label class="field">${t('Korrigiertes tatsächliches Datum','Corrected actual date')}<input id="arrival-corrected" type="date" value="${esc(ARRIVAL.review.date)}"></label><label class="field">${t('Begründung · für Musterperson sichtbar','Reason · visible to sample person')}<textarea id="arrival-correction-note" maxlength="1500">${esc(ARRIVAL.review.note)}</textarea></label><label class="attendance-check"><input id="arrival-correction-checked" type="checkbox" ${ARRIVAL.review.checked?'checked':''}>${t('Geänderte Angabe im Muster geprüft','Changed information reviewed in sample')}</label>${arrivalButton('Korrektur lokal dokumentieren','Record correction locally','correct')}</section>`:''}${arrivalTasksView()}<details><summary>${t('Planfassungen und gemeinsamer Verlauf','Plan versions and shared history')}</summary>${ARRIVAL.plans.map(arrivalPlanSummary).join('')}<ol>${ARRIVAL.history.map(h=>`<li>${esc(h.at)} · ${t(h.de,h.en)} <span class="learning-preserve">${esc(h.note)}</span></li>`).join('')}</ol></details>`}<p class="learning-source">WF-W06-05-01 · W6.5. ${t('Teilweise lokale Umsetzung. Visumprüfung, Behördentermine, Semesterentscheidung, echte Aufgaben-/Nachrichtenintegration und Zuständigkeitskonfiguration bleiben getrennt offen.','Partial local implementation. Visa review, authority appointments, semester decisions, actual task/message integration and responsibility configuration remain separate and open.')}</p></section>`}
function arrivalResetTasks(){for(const x of ARRIVAL.tasks){x.revision=ARRIVAL.revision;x.status='open';x.checked=false;x.response='';x.internal='';x.publicNote='';x.reply=''}}
function arrivalAction(act){ARRIVAL.error=null;
 if(!ARRIVAL_ROUTES.includes(route()))return;
 if(act==='plan'&&!arrivalStaff()){
  const d=arrivalClone(ARRIVAL.draft);for(const k in d)d[k]=d[k].trim();if(!arrivalDateValid(d.date)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(d.time)||!d.flight||!d.airport)return arrivalFail('Gültiges Musterdatum, Uhrzeit, Flugnummer und Flughafen ergänzen.','Add a valid sample date, time, flight number and airport.');
  const p=ARRIVAL.plans.at(-1);if(p&&['date','time','flight','airport'].every(k=>p[k]===d[k]))return arrivalFail('Dieser Reiseplan ist bereits vorgemerkt.','This travel plan is already recorded.');if(p&&!d.reason)return arrivalFail('Änderungsgrund für den neuen Reiseplan ergänzen.','Add a reason for changing the travel plan.');
  ARRIVAL.plans.push({...d,version:ARRIVAL.plans.length+1,at:new Date().toISOString()});arrivalEvent('Reiseplan lokal aktualisiert; keine Ankunft abgeleitet.','Travel plan updated locally; arrival not inferred.',d.reason);ARRIVAL.draft.reason='';
 }else if(act==='arrived'&&!arrivalStaff()){
  if(ARRIVAL.arrival)return arrivalFail('Ankunft bereits gemeldet. Korrektur über die Verwaltungsprüfung.','Arrival already reported. Use administration review for a correction.');if(!ARRIVAL.confirmed||!arrivalDateValid(ARRIVAL.actualDate)||ARRIVAL.actualDate>new Date().toISOString().slice(0,10))return arrivalFail('Tatsächliches Datum bis heute und ausdrückliche Musterbestätigung erforderlich.','An actual date up to today and explicit sample confirmation are required.');
  ARRIVAL.revision=1;ARRIVAL.arrival={date:ARRIVAL.actualDate,actor:'person',at:new Date().toISOString()};ARRIVAL.tasks=Object.keys(ARRIVAL_TASKS).map(kind=>({kind,owner:kind==='presence'?'head':'admin',revision:1,status:'open',internal:'',response:'',checked:false,publicNote:'',reply:'',replies:[],history:[]}));ARRIVAL.confirmed=false;arrivalEvent('Tatsächliche Ankunft selbst gemeldet; drei lokale Anschlussprüfungen angelegt.','Actual arrival self-reported; three local follow-up reviews created.');
 }else if(act==='correct'&&arrivalAllowed()&&ARRIVAL.role==='admin'){
  const d=ARRIVAL.review;if(!ARRIVAL.arrival||!d.checked||!d.note.trim()||!arrivalDateValid(d.date)||d.date>new Date().toISOString().slice(0,10))return arrivalFail('Geprüftes tatsächliches Datum und nachvollziehbare Begründung erforderlich.','A reviewed actual date and traceable reason are required.');if(d.date===ARRIVAL.arrival.date)return arrivalFail('Datum unverändert; keine Korrektur erforderlich.','Date unchanged; no correction needed.');const old=ARRIVAL.arrival.date;ARRIVAL.revision++;ARRIVAL.arrival={date:d.date,actor:'admin',at:new Date().toISOString()};arrivalResetTasks();arrivalEvent('Ankunftsdatum durch Musterverwaltung korrigiert; Anschlussprüfungen erneut offen.','Arrival date corrected by sample administration; follow-up reviews reopened.',old+' → '+d.date+' · '+d.note.trim());ARRIVAL.review={date:'',note:'',checked:false};
 }else return;render();document.getElementById('arrival-heading')?.focus();
}
function arrivalTaskAction(kind,act){if(!ARRIVAL_ROUTES.includes(route()))return;const x=ARRIVAL.tasks.find(x=>x.kind===kind);if(!x)return;
 if(act==='reply'&&!arrivalStaff()){if(x.status!=='clarify'||!x.reply.trim())return arrivalFail('Offene Rückfrage und eigene fiktive Ergänzung erforderlich.','An open question and your fictional additional information are required.');x.replies.push({text:x.reply.trim(),revision:ARRIVAL.revision,at:new Date().toISOString()});x.reply='';x.status='open';x.checked=false;arrivalEvent('Ergänzung zur Anschlussprüfung lokal vorgemerkt.','Additional information for follow-up review recorded locally.');}
 else if(['question','record'].includes(act)&&arrivalAllowed()&&x.owner===ARRIVAL.role){if(!x.checked||!x.internal.trim()||!x.response.trim()||x.revision!==ARRIVAL.revision)return arrivalFail('Aktuelle Ankunftsfassung, Prüfnotiz, Rückmeldung und Prüfbestätigung erforderlich.','Current arrival revision, review note, response and confirmation required.');x.history.push({revision:x.revision,internal:x.internal.trim(),response:x.response.trim(),at:new Date().toISOString()});x.publicNote=x.response.trim();x.status=act==='question'?'clarify':'recorded';x.checked=false;arrivalEvent(act==='question'?'Rückfrage lokal bereitgestellt.':'Prüfstand lokal dokumentiert, keine externe Erledigung.',act==='question'?'Question recorded locally.':'Review recorded locally, no external completion.');}
 else return;ARRIVAL.error=null;render();document.getElementById('arrival-heading')?.focus();
}
const arrivalBodyBefore=v3Body;v3Body=function(r){return ARRIVAL_ROUTES.includes(r)?arrivalPage():arrivalBodyBefore(r)};
const arrivalGuidanceBefore=v3Guidance;v3Guidance=function(a){return ARRIVAL_ROUTES.includes(route())?[t('Geplant ist noch nicht angekommen.','Planned is not yet arrived.'),t('Reiseplanung, eigene Ankunftsmeldung und fachliche Anschlussprüfung bleiben getrennte Schritte.','Travel planning, your arrival report and follow-up review remain separate steps.'),[['Meine Ankunft','My arrival','/portal/arrival'],['Ankunftsprüfung','Arrival review','/staff/arrival']]]:arrivalGuidanceBefore(a)};
const arrivalAssistantBefore=v3Assistant;v3Assistant=function(a){if(!arrivalStaff())return arrivalAssistantBefore(a);const g=v3Guidance(a);return `<aside class="assistant" id="context-companion" aria-label="${t('Ankunftsbegleitung','Arrival guidance')}"><div class="assistant-body"><h2>${g[0]}</h2><p>${g[1]}</p>${g[2].map(([de,en,r])=>`<a class="suggestion" href="#${r}">${t(de,en)}${arrow}</a>`).join('')}<p>${t('Keine Rechts-, Visa-, Semester- oder Zahlungsentscheidung.','No legal, visa, semester or payment decision.')}</p></div></aside>`};
const arrivalBindBefore=v3Bind;v3Bind=function(){arrivalBindBefore();if(!ARRIVAL_ROUTES.includes(route()))return;const refresh=()=>{ARRIVAL.error=null;render();document.getElementById('arrival-heading')?.focus()};document.querySelectorAll('[data-arrival-action]').forEach(e=>e.addEventListener('click',()=>arrivalAction(e.dataset.arrivalAction)));document.querySelectorAll('[data-arrival-task-action]').forEach(e=>e.addEventListener('click',()=>arrivalTaskAction(e.dataset.task,e.dataset.arrivalTaskAction)));document.getElementById('arrival-role')?.addEventListener('change',e=>{if(!['admin','head','other'].includes(e.target.value))return;ARRIVAL.role=e.target.value;ARRIVAL.review.checked=false;ARRIVAL.tasks.forEach(x=>x.checked=false);refresh()});
 for(const key of Object.keys(ARRIVAL.draft))document.getElementById('arrival-'+key)?.addEventListener('input',e=>{if(!arrivalStaff())ARRIVAL.draft[key]=e.target.value});document.getElementById('arrival-actual')?.addEventListener('input',e=>{ARRIVAL.actualDate=e.target.value;ARRIVAL.confirmed=false;const c=document.getElementById('arrival-confirmed');if(c)c.checked=false});document.getElementById('arrival-confirmed')?.addEventListener('change',e=>ARRIVAL.confirmed=e.target.checked);
 for(const [id,key] of [['arrival-corrected','date'],['arrival-correction-note','note']])document.getElementById(id)?.addEventListener('input',e=>{if(!arrivalAllowed()||ARRIVAL.role!=='admin')return;ARRIVAL.review[key]=e.target.value;ARRIVAL.review.checked=false;const c=document.getElementById('arrival-correction-checked');if(c)c.checked=false});document.getElementById('arrival-correction-checked')?.addEventListener('change',e=>ARRIVAL.review.checked=e.target.checked);
 document.querySelectorAll('[data-arrival-task-field]').forEach(e=>e.addEventListener(e.dataset.arrivalTaskField==='checked'?'change':'input',()=>{const x=ARRIVAL.tasks.find(x=>x.kind===e.dataset.task),key=e.dataset.arrivalTaskField;if(!x)return;if(key==='reply'&&!arrivalStaff())x.reply=e.value;else if(arrivalAllowed()&&ARRIVAL.role===x.owner){x[key]=key==='checked'?e.checked:e.value;if(key!=='checked'){x.checked=false;const c=document.querySelector(`[data-arrival-task-field="checked"][data-task="${x.kind}"]`);if(c)c.checked=false}}}));
};
render();
